import items from "../../scripts/v3/rack.json";

// Garments on the homepage rack (illustrative shop; prices are examples).
// Cut-outs in public/assets/rack/<id>.webp, generated by scripts/v3/rack-cutouts.mjs.
export type RackItem = { id: string; name: string; colour: string; price: number; note: string; image: string };

const notes: Record<string, string> = {
  "linen-overshirt": "Washed linen, horn buttons, two chest pockets.",
  "wool-crewneck": "Chunky lambswool, ribbed cuffs and hem.",
  "twill-overshirt": "Brushed cotton twill, point collar.",
  "merino-tee": "Fine merino, crew neck, wears all year.",
  "linen-shirt": "Soft collar, mother-of-pearl buttons.",
  cardigan: "Wool knit, V-neck, wooden buttons.",
  "field-jacket": "Cotton canvas, four patch pockets.",
  "heavy-tee": "Heavyweight cotton, boxy fit.",
  "wool-coat": "Long wool coat, notch lapels.",
  "knit-polo": "Textured knit, three-button placket.",
};

export const rack: RackItem[] = items.map((g) => ({ id: g.id, name: g.name, colour: g.colour, price: g.price, note: notes[g.id] ?? "", image: `/assets/rack/${g.id}.webp` }));
